 plan=read(HERE/'PLAN.json');summary=read(OUT/'SUMMARY.json');profiles=read(OUT/'PROFILE_METRICS.json');pairs=read(OUT/'COMPARISONS.json');audit=read(PHASE/'independent_audit/NUMERICAL_AUDIT.json');dependency=read(PHASE/'independent_audit/SOURCE_PIXEL_DEPENDENCY_AUDIT.json');support=read(PHASE/'independent_audit/MEMBER_CORE_SUPPORT.json');plots=read(OUT/'PLOT_INDEX.json');inv=read(PHASE/'inputs/INPUT_INVENTORY.json');nxt=read(PHASE/'scientific_review/NEXT_GROUP_METADATA.json')
